import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, JSON_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Explicit !!int must still accept signed binary notation in the JSON schema.
    assert.strictEqual(load('!!int -0b101', { schema: JSON_SCHEMA }), -5);
    assert.strictEqual(load('!!int +0b101', { schema: JSON_SCHEMA }), 5);
    assert.strictEqual(load('!!int 0b101', { schema: JSON_SCHEMA }), 5);
    // Input that only matches the new [^-+]?0b branch must still be rejected.
    assert.throws(() => load('!!int "10b101"', { schema: JSON_SCHEMA }));
  });
});

