describe('proof', () => {
  it('resolves positive YAML 1.1 integers that carry an explicit plus sign', () => {
    // The unpatched parser strips a leading '+' before dispatching on the
    // radix prefix, so these load as 31, 5 and 15 respectively.
    // The patch short-circuits the sign check to `false`, leaving the '+'
    // in place, and parseInt('+0x1F', 10) therefore yields 0.
    assert.strictEqual(load('+0x1F', { schema: YAML11_SCHEMA }), 31);
    assert.strictEqual(load('+0b101', { schema: YAML11_SCHEMA }), 5);
    assert.strictEqual(load('+017', { schema: YAML11_SCHEMA }), 15);
  });
});

