import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // "abc" encodes to "YWJj": 4 chars, no padding (btoa("abc") === "YWJj").
    assert.deepStrictEqual(
      Array.from(load('!!binary YWJj', { schema: YAML11_SCHEMA })),
      [0x61, 0x62, 0x63]
    );

    // A single byte encodes with "==" padding (btoa("A") === "QQ==").
    assert.deepStrictEqual(
      Array.from(load('!!binary QQ==', { schema: YAML11_SCHEMA })),
      [0x41]
    );

    // dump emits canonical base64 ("AQID" for [1,2,3]); loading it back must work.
    const round = load(dump(new Uint8Array([1, 2, 3])), { schema: YAML11_SCHEMA });
    assert.deepStrictEqual(Array.from(round), [1, 2, 3]);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    class Point {
      constructor(x, y) {
        this.x = x;
        this.y = y;
      }
    }

    // An object with a custom prototype is not a plain object, so no tag in
    // the default dump schema identifies it; dump() must reject it instead of
    // silently serializing it as a mapping.
    assert.throws(
      () => dump(new Point(1, 2)),
      (err) => err instanceof Error && /unacceptable kind of an object to dump/.test(err.message)
    );
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // isPlainObject must only accept null-prototype and Object.prototype
    // objects. The patch (prototype !== null || prototype === Object.prototype)
    // makes it accept every non-array object, so dumping non-plain objects
    // silently succeeds via mapTag instead of throwing.
    class Point {
      constructor(x, y) {
        this.x = x;
        this.y = y;
      }
    }

    assert.throws(
      () => dump(new Map([['a', 1]])),
      /unacceptable kind of an object to dump/
    );

    assert.throws(
      () => dump(new Point(1, 2)),
      /unacceptable kind of an object to dump/
    );
  });
});
